// Packs pdf.js into a TypeScript file so the app can load it offline.
// Run once after installing pdfjs-dist:  node scripts/build-pdf-assets.mjs
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
const SOURCE = 'node_modules/pdfjs-dist/legacy/build/';
const TARGET = 'src/features/notes/import/pdf/pdfAssets.generated.ts';

const read = (name) => readFileSync(SOURCE + name, 'utf8');

const output = [
  '// GENERATED by scripts/build-pdf-assets.mjs. Do not edit, and avoid opening this file: it is one very long line.',
  `export const PDF_LIB_SOURCE: string = ${JSON.stringify(read('pdf.min.mjs'))};`,
  `export const PDF_WORKER_SOURCE: string = ${JSON.stringify(read('pdf.worker.min.mjs'))};`,
  '',
].join('\n');
mkdirSync(dirname(TARGET), { recursive: true });
writeFileSync(TARGET, output);
console.log(`Wrote ${TARGET} (${(output.length / 1024 / 1024).toFixed(1)} MB)`);